class Solution {
public:
    int arraySign(vector<int>& nums) {
        int neg = 0;
        for (int x : nums) {
            if (x == 0) return 0;
            if (x < 0) neg++;
        }
        return (neg % 2 == 1) ? -1 : 1;
    }
};

class Solution {
    public int arraySign(int[] nums) {
        int neg = 0;
        for (int x : nums) {
            if (x == 0) return 0;
            if (x < 0) neg++;
        }
        return (neg % 2 == 1) ? -1 : 1;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var arraySign = function(nums) {
    let neg = 0;
    for (const x of nums) {
        if (x === 0) return 0;
        if (x < 0) neg++;
    }
    return neg % 2 === 1 ? -1 : 1;
};
